function identityThreatsPanel(d){const tLabel=value=>({'mfa-not-registered':tr('حساب بلا MFA','Account without MFA'),'stale-account':tr('حساب راكد','Stale account'),'password-not-rotated':tr('كلمة مرور قديمة','Password not rotated'),'password-spraying':tr('رش كلمات المرور','Password spraying'),'brute-force':tr('تخمين متكرر','Brute force'),'brute-force-then-success':tr('تخمين ثم نجاح','Brute force then success'),'impossible-travel':tr('سفر مستحيل','Impossible travel'),'new-country-signin':tr('دخول من دولة جديدة','New-country sign-in'),'risky-oauth-consent':tr('موافقة OAuth خطرة','Risky OAuth consent'),'broad-oauth-consent':tr('موافقة OAuth واسعة','Broad OAuth consent'),'idp-change-unauthorized':tr('تعديل IdP بلا تفويض','Unauthorized IdP change'),'idp-change-authorized':tr('تعديل IdP مصرح','Authorized IdP change')})[value]||value;const counts=Object.entries(d.by_type).map(([k,v])=>`${h(tLabel(k))}: ${v}`).join(' · ');return `<div class="divider"></div><section class="panel"><div class="panel-head"><h2>${tr('اكتشاف تهديدات الهوية','Identity threat detection')} · CG-015</h2></div><div class="panel-body"><div class="hint">${h(d.claim)}</div><div class="secondary">${counts||tr('لا نتائج','No findings')}<br>${tr('التغطية','Coverage')}: ${tr('حسابات','accounts')} ${d.coverage.accounts} (MFA ${tr('معروف','known')} ${d.coverage.mfa_known}) · ${tr('عمليات دخول','sign-ins')} ${d.coverage.signins} · OAuth ${d.coverage.consents} · IdP ${d.coverage.idp_changes}</div>${table([tr('النتيجة','Finding'),tr('الموضوع','Subject'),tr('التفاصيل','Detail'),tr('الدليل','Directory / evidence')],d.items.map(f=>[`${h(tLabel(f.type))}<div class="secondary">${pill(f.severity)}</div>`,`<span class="mono">${h(f.subject)}</span>`,h(f.detail),`<span class="mono">${h(f.directory_ref)}</span><br>${button('event',tr('دليل الهوية','Identity evidence'),f.event_id,'text-button')}`]),tr('لا توجد نتائج تهديدات هوية','No identity threat findings'),d)}</div></section>`;}
async function identityAuditView(){const [base,audits,laps,adcs,pam,saas,correlations,helpdesk,directories,threats]=await Promise.all([capabilityView(),api('/api/directory-audits?limit=100'),api('/api/laps-posture?limit=100'),api('/api/adcs-kerberos-posture?limit=100'),api('/api/privileged-access?limit=100'),api('/api/saas-service-inventory?limit=100'),api('/api/identity-attack-correlations?limit=100'),api('/api/helpdesk-resets?limit=100'),api('/api/identity-directories?limit=50'),api('/api/identity-threats?limit=100')]);return base+identityThreatsPanel(threats)+identityDirectoriesPanel(directories)+directoryAuditPanel(audits)+lapsPosturePanel(laps)+adcsKerberosPanel(adcs)+privilegedAccessPanel(pam)+saasServiceInventoryPanel(saas)+identityAttackCorrelationPanel(correlations)+helpdeskResetPanel(helpdesk);}
async function render(){if(!state.user)return;const generation=++state.generation;try{const kind=viewKind();const html=kind==='overview'?await overview():kind==='discovery'?await discoveryView():kind==='sources'?await sourcesView():kind==='settings'?await usersView():state.view==='network-map'?await visibilityGapsView():state.view==='policies'?await securityOutcomesView():state.view==='reports'?await riskRegisterView():state.view==='threats'?await threatsView():state.view==='identity'?await identityAuditView():state.view==='vulnerabilities'?await vulnerabilitiesView():capabilityCatalog[state.view]?await capabilityView():await listView();if(generation===state.generation&&state.user){shell(html);if(['sources','discovery'].includes(kind)&&state.user.role==='admin'){const b=document.createElement('button');b.type='button';b.dataset.action='local-inventory';b.className='small ghost';b.textContent=tr('جرد هذا الجهاز','Inventory this host');document.querySelector('.heading-actions').append(b);}}}catch(e){toast(e.message,true);}}
function detail(name,value){return `<div class="detail-item"><small>${h(name)}</small><strong>${value}</strong></div>`;}
async function assetModal(id){const a=await api(`/api/assets/${id}`);modal(a.hostname||a.external_id,`<div class="detail-grid">${detail(tr('النظام والنوع','OS / type'),`${h(a.os_family)} / ${h(a.device_type)}`)}${detail(tr('الرؤية','Visibility'),pill(a.visibility))}${detail(tr('العناوين','Addresses'),`<span class="mono">${h(a.addresses.join(', ')||tr('غير معروف','Unknown'))}</span>`)}${detail(tr('المصدر','Source'),h(a.source.name))}${detail(tr('المالك','Owner'),h(a.governance_context.owner?`${a.governance_context.owner.display_name} (${a.governance_context.owner.owner_id})`:tr('غير معروف','Unknown')))}${detail(tr('الخدمة التجارية/التشغيلية','Business / operational service'),h(a.governance_context.business_service||tr('غير معروف','Unknown')))}${detail(tr('الموقع','Site'),h(a.governance_context.site||tr('غير معروف','Unknown')))}${detail(tr('حساسية البيانات','Data sensitivity'),pill(a.governance_context.data_sensitivity))}${detail(tr('حرجية الخدمة','Service criticality'),pill(a.governance_context.service_criticality||'unknown'))}${detail(tr('المنتج والإصدار','Product / version'),h(a.lifecycle.product?`${a.lifecycle.product.vendor} ${a.lifecycle.product.name} ${a.lifecycle.product.version}${a.lifecycle.product.edition?` ${a.lifecycle.product.edition}`:''}`:tr('غير معروف','Unknown')))}${detail(tr('إصدار نظام التشغيل','OS lifecycle version'),h(a.lifecycle.operating_system?`${a.lifecycle.operating_system.name} ${a.lifecycle.operating_system.version}${a.lifecycle.operating_system.build?` (${a.lifecycle.operating_system.build})`:''}`:tr('غير معروف','Unknown')))}${detail(tr('حالة دعم الشركة','Vendor support status'),pill(a.lifecycle.vendor_support.status))}${detail(tr('نهاية الدعم القياسي','Standard support end'),h(date(a.lifecycle.vendor_support.standard_support_end)))}${detail(tr('نهاية التحديثات الأمنية','Security updates end'),h(date(a.lifecycle.vendor_support.security_updates_end)))}${detail(tr('الدعم الممتد','Extended support'),h(a.lifecycle.vendor_support.extended_support.available?`${a.lifecycle.vendor_support.extended_support.enrolled?tr('مشترك','Enrolled'):tr('متاح غير مشترك','Available, not enrolled')} · ${date(a.lifecycle.vendor_support.extended_support.end_at)}`:tr('غير متاح','Not available')))}${detail(tr('محرك الحماية المبلغ عنه','Reported protection engine'),h(a.protection.engine||tr('غير معروف','Unknown')))}${detail(tr('إثبات المنع','Prevention verification'),pill('not-tested'))}</div><p class="form-note">${tr('نوافذ الصيانة','Maintenance windows')}: ${h(a.governance_context.maintenance_windows.join(' · ')||tr('غير معروفة','Unknown'))}${a.governance_context.event_id?` · ${button('event',tr('دليل السياق','Context evidence'),a.governance_context.event_id,'text-button')}`:''}</p><p class="form-note">${tr('خطة التحديث أو الاستبدال','Upgrade / replacement plan')}: ${a.lifecycle.plan?h(`${label(a.lifecycle.plan.action)} · ${a.lifecycle.plan.target} · ${a.lifecycle.plan.owner_id} · ${date(a.lifecycle.plan.due_at)} · ${label(a.lifecycle.plan.status)}`):tr('غير معروفة','Unknown')}${a.lifecycle.event_id?` · ${button('event',tr('دليل دورة الحياة','Lifecycle evidence'),a.lifecycle.event_id,'text-button')}`:''}</p><p class="form-note">${tr('مثبت / يعمل / يجمع بيانات','Installed / running / collecting')}: <span class="mono">${h([a.protection.installed,a.protection.running,a.protection.collecting].map(x=>x===null||x===undefined?'unknown':String(x)).join(' / '))}</span></p><div class="form-actions">${button('report',`${icon('download')} ${tr('تقرير الأدلة','Evidence report')}`,a.id,'small')}${canWrite()?button('new-action',tr('طلب تغيير الأهمية','Request criticality change'),a.id,'small primary'):''}</div><section class="detail-section"><h3>${tr('الأحداث الأخيرة','Recent events')}</h3>${a.events.map(e=>`<div class="list-row"><div class="grow"><strong class="mono">${h(e.kind)}</strong><p>${h(date(e.observed_at))}</p></div>${button('event',tr('الدليل','Evidence'),e.id)}</div>`).join('')||'<p>—</p>'}</section><section class="detail-section"><h3>${tr('التنبيهات المرتبطة','Related alerts')}</h3>${a.alerts.map(x=>`<div class="list-row">${pill(x.severity)}${button('alert',h(x.title),x.id,'text-button')}</div>`).join('')||'<p>—</p>'}</section>`);}
async function alertModal(id){const a=await api(`/api/alerts/${id}`);modal(tr('تفاصيل التنبيه','Alert details'),`${pill(a.severity)} ${pill(a.status)}<h3 class="detail-section">${h(a.title)}</h3><p class="mono">${h(a.rule_id)} / ${h(a.rule_version)}</p><p class="form-note">${tr('عدد التكرارات','Occurrences')}: ${a.occurrences} · ${h(date(a.last_seen))}</p><section class="detail-section"><h3>${tr('مراجع الأدلة','Evidence references')}</h3>${a.evidence_ids.map(e=>`<p>${button('event',h(e),e,'text-button mono')}</p>`).join('')||`<p>${tr('تنبيه صحة مصدر؛ يعتمد على انقطاع الاستلام.','Source health alert based on missing receipt.')}</p>`}</section><div class="form-actions">${a.asset_id?button('asset',tr('الأصل','Asset'),a.asset_id):''}${canWrite()&&a.status==='open'?button('ack',tr('إقرار الاستلام','Acknowledge'),a.id,'small primary'):''}${canWrite()?button('new-case',tr('فتح تحقيق','Open investigation'),a.id):''}</div>`);}
async function caseModal(id){const c=await api(`/api/cases/${id}`);modal(c.title,`${pill(c.status)}<div class="form-actions">${button('case-report',`${icon('download')} ${tr('تنزيل حزمة الأدلة','Download evidence pack')}`,id,'small')}</div><section class="detail-section"><h3>${tr('التنبيهات','Alerts')}</h3>${c.alert_ids.map(a=>`<p>${button('alert',h(a.slice(0,8)),a,'text-button mono')}</p>`).join('')}</section><section class="detail-section"><h3>${tr('سجل التحقيق','Investigation timeline')}</h3>${c.notes.map(n=>`<div class="note"><small class="muted">${h(date(n.at))} · <bdi class="mono">${h(n.actor.slice(0,8))}</bdi></small><p>${h(n.text)}</p></div>`).join('')||`<p>${tr('لم تُضف ملاحظات بعد.','No notes yet.')}</p>`}</section>${canWrite()?`<form data-form="case-note" data-id="${id}" class="detail-section"><div class="form-grid"><label class="full">${tr('قرار أو ملاحظة','Decision or note')}<textarea name="note" maxlength="4000" required></textarea></label><label>${tr('حالة التحقيق','Case status')}<select name="status">${['open','investigating','closed'].map(x=>`<option value="${x}" ${c.status===x?'selected':''}>${h(label(x))}</option>`).join('')}</select></label></div><div class="form-actions"><button class="primary">${tr('حفظ الملاحظة','Save note')}</button></div><div id="form-error" role="alert" hidden></div></form>`:''}`);}
async function actionModal(id){const a=await api(`/api/actions/${id}`);modal(tr('مراجعة إجراء محلي','Review local action'),`${pill(a.status)}<div class="hint">${tr('هذا الإجراء يعدّل أهمية الأصل داخل CyberGuard فقط. لا يغير الجهاز أو الشبكة.','This changes asset criticality inside CyberGuard only. It does not change a device or network.')}</div><div class="detail-grid">${detail(tr('قبل','Before'),h(label(a.before_value)))}${detail(tr('بعد','After'),h(label(a.after_value)))}${detail(tr('صاحب الطلب','Requested by'),`<span class="mono">${h(a.requested_by)}</span>`)}${detail(tr('انتهاء الموافقة','Approval expiry'),h(date(a.expires_at)))}</div><p>${h(a.reason)}</p><div class="detail-grid">${detail(tr('نتيجة المحاكاة','Dry-run result'),pill(a.dry_run.result))}${detail(tr('السجلات المتأثرة','Affected records'),h(a.impact_analysis.affected_records))}${detail(tr('تأثير الجهاز/الشبكة','Endpoint / network impact'),`${a.impact_analysis.endpoint_changes} / ${a.impact_analysis.network_changes}`)}</div><p class="mono detail-section">Preflight: ${h(a.preflight_hash)}</p><p class="form-note">${tr('خطة التراجع','Rollback plan')}: ${h(a.rollback_plan.method)} · ${h(a.rollback_plan.guard)}</p><section class="detail-section"><h3>${tr('دورة الإجراء وسجل التدقيق','Action lifecycle and audit')}</h3>${a.lifecycle.map(x=>`<div class="list-row"><span class="mono">${h(x.action)}</span><span>${h(date(x.at))}</span></div>`).join('')}<p class="form-note">${tr('سلامة سلسلة التدقيق المحلية','Local audit-chain integrity')}: ${h(String(a.audit_chain.valid))}</p></section>${a.result?`<p class="hint">${h(a.result)}</p>`:''}<div class="form-actions">${state.user.role==='admin'&&a.status==='pending-approval'&&a.requested_by!==state.user.id?button('approve-action',tr('اعتماد المعاينة','Approve preview'),id,'primary'):''}${state.user.role==='admin'&&a.status==='approved'?button('execute-action',tr('تنفيذ التغيير المحلي','Execute local change'),id,'primary'):''}${state.user.role==='admin'&&a.status==='verified'?button('rollback-action',tr('التراجع عن التغيير المحلي','Roll back local change'),id,'danger'):''}</div>${a.status==='pending-approval'&&a.requested_by===state.user.id?`<p class="form-note">${tr('يجب أن يراجع الطلب مسؤول آخر بحسابه قبل التنفيذ.','Another administrator must review this request using their own account.')}</p>`:''}`);}
function sourceTokenModal(result){modal(tr('هوية المصدر — تظهر مرة واحدة','Source credential — shown once'),`<div class="hint">${tr('احفظ المفتاح في مخزن أسرار. لن يُعرض مجددًا، ويمكن تدويره أو إبطاله.','Save the credential in a secret store. It cannot be retrieved again; rotate or revoke it when needed.')}</div><label>${tr('مفتاح المصدر','Source token')}<input id="source-token" type="password" value="${h(result.token)}" readonly autocomplete="off"></label><p class="form-note">${tr('حدد الحقل وانسخ محتواه دون إظهاره على الشاشة.','Select the field and copy its contents without revealing it on screen.')}</p><div class="json">POST /api/sources/${h(result.id)}/events<br>Authorization: Bearer &lt;source-token&gt;<br>Content-Type: application/json</div><div class="form-actions">${button('close',tr('حُفظ المفتاح، إغلاق','Close'),'','primary')}</div>`);}
function sound(){try{const context=new AudioContext(),osc=context.createOscillator(),gain=context.createGain();osc.frequency.value=740;gain.gain.setValueAtTime(.055,context.currentTime);gain.gain.exponentialRampToValueAtTime(.001,context.currentTime+.45);osc.connect(gain);gain.connect(context.destination);osc.start();osc.stop(context.currentTime+.5);osc.onended=()=>context.close();}catch{toast(tr('الصوت غير متاح في هذا المتصفح.','Sound is unavailable in this browser.'),true);}}

document.addEventListener('click',async event=>{const element=event.target.closest('[data-action]');if(!element)return;const action=element.dataset.action,id=element.dataset.id;try{
  if(action==='severity'){state.severity=id;await render();return;}
  if(action==='capability'){const name={vulnerability:tr('فحص الثغرات','Vulnerability Scanner'),edr:'EDR',ids:'IDS / IPS',email:tr('أمن البريد','Email Security'),casb:'CASB'}[id]||id;modal(name,`<div class="hint">${tr('هذا التكامل لم يُنفذ بعد. البطاقة توضح موضعه في المنصة؛ لا يبدأ الزر فحصًا أو إجراء حماية.','This integration is not implemented yet. This card shows its place in the platform; it does not start a scan or a protection action.')}</div><p>${tr('راجع تغطية المتطلبات لمعرفة التنفيذ والاختبارات والقيود الحالية.','Review product coverage for current implementation, tests and limitations.')}</p><div class="form-actions">${button('close',tr('إغلاق','Close'),'','primary')}</div>`);return;}
  if(action==='close'){dialog.close();return;}
  if(action==='language'){state.lang=state.lang==='ar'?'en':'ar';if(state.user){dialog.close();await render();}else await authPage(element.dataset.setup==='true');return;}
  if(action==='nav'){state.view=id==='discover'&&element.closest('.form-actions')?'sources':id;state.q='';state.offset=0;await render();return;}
  if(action==='refresh'){await render();return;}
  if(action==='prev'||action==='next'){state.offset=Math.max(0,state.offset+(action==='next'?25:-25));await render();return;}
  if(action==='logout'){await api('/api/auth/logout',{});state.user=null;state.csrf=null;dialog.close();await authPage(false);return;}
  if(action==='siren'){state.siren=!state.siren;if(state.siren)sound();await render();return;}
  if(action==='asset'){await assetModal(id);return;}
  if(action==='report'){download(await api(`/api/assets/${id}/report`),`cyberguard-evidence-${id}.json`);return;}
  if(action==='event'){const e=await api(`/api/events/${id}`);modal(tr('دليل الحدث المنقح','Redacted event evidence'),`<div class="hint">${tr('هذا سجل منقح. البصمة الأصلية مرجع مقارنة، ولا يعني ذلك تخزين النص الأصلي الحساس.','This is a redacted record. The original hash is a comparison reference; sensitive raw content is not stored.')}</div><pre class="json">${h(JSON.stringify(e,null,2))}</pre>`);return;}
  if(action==='alert'){await alertModal(id);return;}
  if(action==='ack'){await api(`/api/alerts/${id}/ack`,{});dialog.close();toast(tr('تم الإقرار بالتنبيه.','Alert acknowledged.'));await render();return;}
  if(action==='case'){await caseModal(id);return;}
  if(action==='case-report'){download(await api(`/api/cases/${id}/report`),`cyberguard-case-${id}.json`);return;}
  if(action==='action'){await actionModal(id);return;}
  if(['approve-action','execute-action','rollback-action'].includes(action)){await api(`/api/actions/${id}/${action.split('-')[0]}`,{});await actionModal(id);await render();return;}
  if(action==='verify-audit'){const r=await api('/api/audit/verify');modal(tr('فحص سلسلة التدقيق','Audit chain verification'),`<div class="${r.valid?'success-message':'error'}">${r.valid?tr(`نجح فحص ${r.checked} سجلًا.`,`Verified ${r.checked} records.`):tr('فشل التحقق من السلسلة.','Chain verification failed.')}</div><p class="form-note">${tr('الفحص محلي؛ لا يكشف إعادة كتابة السلسلة كاملة بواسطة مدير قاعدة البيانات دون تثبيت خارجي.','Local verification cannot detect a complete chain rewrite by a database administrator without external anchoring.')}</p><pre class="json">${h(r.head||'')}</pre>`);return;}
  if(action==='new-source'){modal(tr('إضافة مصدر بيانات','Add data source'),`<form data-form="source"><div class="form-grid"><label class="full">${tr('اسم المصدر','Source name')}<input name="name" maxlength="100" required></label><label>${tr('نوع المصدر','Source type')}<select name="source_type"><option value="generic">Generic</option><option value="managed-agent">Managed Agent</option><option value="log-forwarder">Log Forwarder</option><option value="network-collector">Network Collector</option></select></label><label>${tr('فقد الرؤية بعد (ثانية)','Stale after (seconds)')}<input name="stale_seconds" type="number" min="30" max="86400" value="300" required></label></div><p class="form-note detail-section">${tr('تُنشأ هوية مستقلة لهذا المصدر. يتطلب الاستيراد cg.telemetry/1.','An independent source credential is created. Import uses cg.telemetry/1.')}</p><div id="form-error" role="alert" hidden></div><div class="form-actions"><button class="primary">${tr('إنشاء المصدر','Create source')}</button></div></form>`);return;}
  if(action==='local-inventory'){modal(tr('جرد الجهاز المحلي — قراءة فقط','Local host inventory — read only'),`<p>${tr('سيُقرأ اسم هذا الجهاز وعائلة نظامه وعناوين واجهاته فقط. لن يُجمع اسم المستخدم أو كلمات مرور أو محتوى ملفات، ولن تُفحص الشبكة أو تُعدّل إعدادات.','Reads only this host’s name, OS family and interface addresses. No user names, passwords, file contents, network probes or configuration changes.')}</p><div class="form-actions">${button('confirm-local-inventory',tr('جمع هذه البيانات وحفظها محليًا','Collect and store locally'),'','primary')}</div>`);return;}
  if(action==='confirm-local-inventory'){await api('/api/collectors/local',{confirm_read_only:true});dialog.close();toast(tr('حُفظ جرد الجهاز المحلي. حالة الحماية تبقى غير متحققة.','Local inventory stored. Prevention remains unverified.'));await render();return;}
  if(action==='source-secret'||action==='revoke-source'){modal(tr('مراجعة صلاحية المصدر','Review source access'),`<p>${action==='source-secret'?tr('تدوير المفتاح يبطل المفتاح السابق فورًا. حدّث إعداد الموصل بالمفتاح الجديد.','Rotation immediately invalidates the previous token. Update the collector with the new credential.'):tr('الإبطال يوقف استقبال الأحداث من هذا المصدر ويظهر فجوة رؤية.','Revocation stops ingestion from this source and creates a visibility gap.')}</p><div class="form-actions">${button(action==='source-secret'?'confirm-rotate':'confirm-revoke',tr('تنفيذ','Confirm'),id,'danger')}</div>`);return;}
  if(action==='confirm-rotate'){sourceTokenModal(await api(`/api/sources/${id}/rotate`,{}));await render();return;}
  if(action==='confirm-revoke'){await api(`/api/sources/${id}/revoke`,{});dialog.close();await render();return;}
  if(action==='import'){modal(tr('استيراد أدلة JSON','Import JSON evidence'),`<div class="hint">${tr('يُحفظ الاستيراد كله ضمن معاملة واحدة. لا يُنفذ أي أمر من الملف.','The entire import is committed atomically. No commands from the file are executed.')}</div><form data-form="import" data-id="${id}"><label>${tr('ملف cg.telemetry/1 أو cg.windows-export/1 — حتى 2 MB و250 حدثًا','cg.telemetry/1 or cg.windows-export/1 file — up to 2 MB and 250 events')}<input type="file" name="file" accept=".json,application/json" required></label><div id="form-error" role="alert" hidden></div><div class="form-actions"><button class="primary">${tr('فحص واستيراد','Validate and import')}</button></div></form>`);return;}
  if(action==='sample'){download({schema_version:'cg.telemetry/1',events:[{event_id:`synthetic-${Date.now()}`,kind:'asset.observed',observed_at:new Date().toISOString(),asset:{external_id:'SYNTHETIC-LAB-ONLY-001',hostname:'SYNTHETIC-NOT-A-REAL-DEVICE',os_family:'unknown',device_type:'unknown',addresses:['192.0.2.10']},details:{}}]},'SYNTHETIC-ONLY-cg-telemetry.json');return;}
  if(action==='sample-discovery'){download({schema_version:'cg.telemetry/1',events:[{event_id:`synthetic-discovery-${Date.now()}`,kind:'discovery.observed',observed_at:new Date().toISOString(),asset:{external_id:'SYNTHETIC-DISCOVERY-001',hostname:'SYNTHETIC-SWITCH',os_family:'network',device_type:'switch',addresses:['192.0.2.20']},details:{authorization_ref:'SYNTHETIC-AUTHORIZATION-REFERENCE',acquisition:'passive-import',availability:'up',networks:['192.0.2.0/24'],routes:[{destination:'0.0.0.0/0',gateway:'192.0.2.1',interface:'uplink'}],vlans:[{id:10,name:'SYNTHETIC-LAB'}],interfaces:[{name:'Gi1/0/1',status:'up',vlan:10}],services:[{transport:'tcp',port:443,state:'observed-open',name:'https-management',evidence:'source-report'}]}}]},'SYNTHETIC-ONLY-authorized-discovery.json');return;}
  if(action==='new-case'){modal(tr('فتح تحقيق أمني','Open security investigation'),`<form data-form="case" data-id="${id}"><label>${tr('عنوان التحقيق','Investigation title')}<input name="title" maxlength="200" required></label><div id="form-error" role="alert" hidden></div><div class="form-actions"><button class="primary">${tr('فتح التحقيق','Open investigation')}</button></div></form>`);return;}
  if(action==='new-user'){modal(tr('إضافة مستخدم محلي','Create local user'),`<form data-form="user"><div class="form-grid"><label>${tr('اسم المستخدم','Username')}<input name="username" pattern="[A-Za-z0-9_.-]{3,64}" maxlength="64" required autocomplete="off"></label><label>${tr('الدور','Role')}<select name="role"><option value="viewer">${tr('مشاهد','Viewer')}</option><option value="analyst">${tr('محلل','Analyst')}</option><option value="admin">${tr('مسؤول','Administrator')}</option></select></label><label class="full">${tr('كلمة مرور — 14 حرفًا على الأقل','Password — at least 14 characters')}<input name="password" type="password" minlength="14" maxlength="256" required autocomplete="new-password"></label></div><div id="form-error" role="alert" hidden></div><div class="form-actions"><button class="primary">${tr('إنشاء الحساب','Create account')}</button></div></form>`);return;}
  if(action==='new-action'){modal(tr('معاينة تغيير أهمية الأصل','Preview asset criticality change'),`<div class="hint">${tr('تغيير محلي في سجل الأصل؛ لا إجراء على الجهاز. يحتاج موافقة مسؤول آخر.','A local record change, not a device action. A second administrator must approve.')}</div><form data-form="action" data-id="${id}"><div class="form-grid"><label>${tr('الأهمية الجديدة','New criticality')}<select name="criticality">${['standard','important','critical'].map(x=>`<option value="${x}">${h(label(x))}</option>`).join('')}</select></label><label>${tr('الصلاحية (ثانية)','Validity (seconds)')}<input type="number" name="ttl_seconds" min="60" max="3600" value="600" required></label><label class="full">${tr('السبب وتقدير الأثر','Reason and impact')}<textarea name="reason" maxlength="1000" required></textarea></label></div><div id="form-error" role="alert" hidden></div><div class="form-actions"><button class="primary">${tr('إنشاء المعاينة','Create preview')}</button></div></form>`);return;}
  if(action==='requirement'){const r=(await api(`/api/requirements?q=${encodeURIComponent(id)}`)).items.find(x=>x.id===id);modal(id,`<p>${h(r.raw_requirement)}</p><pre class="json">${h(JSON.stringify({...r,raw_requirement:undefined},null,2))}</pre>`);return;}
}catch(e){toast(e.message,true);}});

document.addEventListener('submit',async event=>{const form=event.target.closest('[data-form]');if(!form)return;event.preventDefault();const type=form.dataset.form,input=Object.fromEntries(new FormData(form).entries()),submit=form.querySelector('button[type="submit"],button.primary');if(submit)submit.disabled=true;const error=form.querySelector('#form-error');if(error)error.hidden=true;try{
  if(type==='setup'){await api('/api/auth/setup',input);await authPage(false);toast(tr('تم إنشاء المسؤول. سجّل الدخول بكلمة مرورك.','Administrator created. Sign in with your password.'));return;}
  if(type==='login'){const r=await api('/api/auth/login',input);state.user=r.user;state.csrf=r.csrf;state.view='overview';await render();return;}
  if(type==='search'){state.q=input.q;state.offset=0;await render();return;}
  if(type==='global-search'){state.view='threats';state.q=input.q||'';state.offset=0;await render();return;}
  if(type==='source'){sourceTokenModal(await api('/api/sources',{name:input.name,source_type:input.source_type,stale_seconds:Number(input.stale_seconds)}));await render();return;}
  if(type==='user'){await api('/api/users',input);dialog.close();toast(tr('أُنشئ المستخدم.','User created.'));await render();return;}
  if(type==='import'){const file=form.querySelector('[name=file]').files[0];if(!file||file.size>2*1024*1024)throw new Error(tr('اختر ملفًا لا يتجاوز 2 MB.','Select a file no larger than 2 MB.'));let data;try{data=JSON.parse(await file.text());}catch{throw new Error(errorText('invalid_json'));}const r=await api(`/api/sources/${form.dataset.id}/events`,data);dialog.close();toast(tr(`حُفظ ${r.accepted} حدثًا. المتكرر: ${r.duplicates}. المستبعد غير المدعوم: ${r.parser_report?.skipped.length||0}.`,`Stored ${r.accepted} events. Duplicates: ${r.duplicates}. Unsupported records skipped: ${r.parser_report?.skipped.length||0}.`));await render();return;}
  if(type==='case'){const c=await api('/api/cases',{title:input.title,alert_ids:[form.dataset.id]});await caseModal(c.id);await render();return;}
  if(type==='case-note'){await api(`/api/cases/${form.dataset.id}`,input);await caseModal(form.dataset.id);await render();return;}
  if(type==='action'){const a=await api('/api/actions/preview',{type:'asset.set-criticality',asset_id:form.dataset.id,criticality:input.criticality,reason:input.reason,ttl_seconds:Number(input.ttl_seconds)});await actionModal(a.id);await render();return;}
}catch(e){if(error){error.textContent=e.message;error.className='error';error.hidden=false;}else toast(e.message,true);}finally{if(submit)submit.disabled=false;}});

async function start(){try{const setup=await api('/api/setup/status');if(setup.setup_required){await authPage(true);return;}try{const me=await api('/api/auth/me');state.user=me.user;state.csrf=me.csrf;await render();}catch{await authPage(false);}}catch(e){app.innerHTML=`<main id="main" class="loading"><div class="error">${h(e.message)}</div></main>`;}}
setInterval(()=>{if(state.user&&state.view==='overview'&&!dialog.open&&!document.hidden&&!document.activeElement?.closest('button,input,select,textarea'))render();},30000);
start();
